import { useFrame } from '@react-three/fiber'
import { lazyModule, useNodeRenderer, useWorld, type Vec3 } from '@runek/core'
import { useEffect, useMemo, useRef } from 'react'
import * as THREE from 'three'
import type { WaterShape } from './nodes/water'

// The WebGPU (TSL) twin of the shader below, loaded only under a node renderer.
const waterNodes = lazyModule(() => import('./nodes/water'))
const WATER: WaterShape = {
  freq: [0.045, 0.035, 0.018, 0.06, 0.09],
  chop: 1.4,
  eps: 1.5,
  world: true,
  sky: 0.5,
  glint: [80, 0.8],
  crest: 0.35,
  alpha: [0.86, 0.14],
  fog: true,
}

export interface OceanProps {
  position?: Vec3
  rotation?: Vec3
  /** Accepted for the component contract; this component has no seeded variation yet. */
  seed?: number
  /** Plane size `[width, depth]`, in units. With `follow` on (the default) this patch tracks
   *  the camera, so keep it large enough to reach past the world fog. */
  size?: [number, number]
  /** Defaults to the world palette's `waterDeep` slot. */
  colorDeep?: string
  /** Defaults to the world palette's `waterShallow` slot. */
  colorShallow?: string
  /** Direction the sun glint comes from; pair with your Sky's `sunPosition`. */
  sunPosition?: Vec3
  waveHeight?: number
  waveSpeed?: number
  segments?: number
  /** Track the camera horizontally for an endless sea (default true). Set false to pin it. */
  follow?: boolean
}

const VERTEX = /* glsl */ `
  uniform float uTime;
  uniform float uWaveHeight;
  uniform float uWaveSpeed;
  varying vec3 vWorldPos;
  varying vec3 vNormal;
  varying float vWave;

  // Long, slow ocean swells (lower frequencies than a Lake's chop).
  float waveH(vec2 q, float t) {
    float w1 = sin(q.x * 0.045 + t) * cos(q.y * 0.035 + t * 0.8);
    float w2 = sin(q.x * 0.018 - t * 0.7) * sin(q.y * 0.06 + t);
    float w3 = sin((q.x + q.y) * 0.09 + t * 1.4) * 0.25;
    return (w1 + w2 + w3) * 0.5;
  }

  void main() {
    float t = uTime * uWaveSpeed;
    // World-space horizontal coords of the undisplaced vertex, so the swells stay put in the
    // world even as the mesh follows the camera (no swimming).
    vec2 wxz = (modelMatrix * vec4(position.x, position.y, 0.0, 1.0)).xz;
    float h = waveH(wxz, t);
    vWave = h;

    vec3 p = position;
    p.z += h * uWaveHeight;

    float eps = 1.5;
    float hx = waveH(wxz + vec2(eps, 0.0), t);
    float hy = waveH(wxz + vec2(0.0, eps), t);
    vec3 n = normalize(vec3(-(hx - h) * uWaveHeight / eps, -(hy - h) * uWaveHeight / eps, 1.0));
    vNormal = normalize(mat3(modelMatrix) * n);

    vWorldPos = (modelMatrix * vec4(p, 1.0)).xyz;
    gl_Position = projectionMatrix * viewMatrix * vec4(vWorldPos, 1.0);
  }
`

const FRAGMENT = /* glsl */ `
  uniform vec3 uColorDeep;
  uniform vec3 uColorShallow;
  uniform vec3 uSunDir;
  uniform vec3 uFogColor;
  uniform float uFogNear;
  uniform float uFogFar;
  varying vec3 vWorldPos;
  varying vec3 vNormal;
  varying float vWave;

  void main() {
    vec3 n = normalize(vNormal);
    vec3 viewDir = normalize(cameraPosition - vWorldPos);

    float m = smoothstep(-1.0, 1.0, vWave);
    vec3 col = mix(uColorDeep, uColorShallow, m);

    // sky tint at grazing angles
    float fresnel = pow(1.0 - max(dot(n, viewDir), 0.0), 3.0);
    col = mix(col, vec3(0.62, 0.78, 0.9), fresnel * 0.5);

    // sun glint
    vec3 r = reflect(-uSunDir, n);
    float glint = pow(max(dot(r, viewDir), 0.0), 80.0);
    col += vec3(1.0, 0.95, 0.85) * glint * 0.8;

    // crest brighten
    col += pow(max(m - 0.6, 0.0), 2.0) * 0.35;

    float alpha = 0.86 + fresnel * 0.14;

    // Blend into the world's distance fog so the far sea melts into the sky/horizon.
    float fogF = smoothstep(uFogNear, uFogFar, distance(cameraPosition, vWorldPos));
    col = mix(col, uFogColor, fogF);
    alpha = mix(alpha, 1.0, fogF);

    gl_FragColor = vec4(col, alpha);
  }
`

/** Procedural animated ocean (no textures), decorative (no collider). It follows the camera
 *  horizontally so it reads as open sea to the horizon, with world-space swells that stay put
 *  as it moves and a fog blend that melts the far water into the sky. The surface sits at the
 *  world ground baseline by default (CONTRACT §10); an explicit `position` height wins. */
export function Ocean({
  position,
  rotation = [0, 0, 0],
  size = [400, 400],
  colorDeep,
  colorShallow,
  sunPosition = [80, 30, 40],
  waveHeight = 0.4,
  waveSpeed = 0.6,
  segments = 160,
  follow = true,
}: OceanProps) {
  const { unit, palette, ground } = useWorld()
  const deep = colorDeep ?? palette.waterDeep
  const shallow = colorShallow ?? palette.waterShallow
  const y = position?.[1] ?? ground
  const w = size[0] * unit
  const d = size[1] * unit
  const meshRef = useRef<THREE.Mesh>(null)

  const uniforms = useMemo(
    () => ({
      uTime: { value: 0 },
      uWaveHeight: { value: waveHeight * unit },
      uWaveSpeed: { value: waveSpeed },
      uColorDeep: { value: new THREE.Color(deep) },
      uColorShallow: { value: new THREE.Color(shallow) },
      uSunDir: { value: new THREE.Vector3(...sunPosition).normalize() },
      uFogColor: { value: new THREE.Color('#ffffff') },
      uFogNear: { value: 1e6 },
      uFogFar: { value: 1e7 },
    }),
    [waveHeight, waveSpeed, deep, shallow, sunPosition, unit],
  )

  const nodes = useNodeRenderer() ? waterNodes() : null
  const nodeMaterial = useMemo(
    () => nodes?.waterMaterial(uniforms, WATER) ?? null,
    [nodes, uniforms],
  )
  useEffect(() => () => nodeMaterial?.dispose(), [nodeMaterial])

  useFrame((state, delta) => {
    uniforms.uTime.value += delta
    // Mirror the world's distance fog so the ocean horizon matches everything else.
    const fog = state.scene.fog
    if (fog && 'near' in fog) {
      const linear = fog as THREE.Fog
      uniforms.uFogColor.value.copy(linear.color)
      uniforms.uFogNear.value = linear.near
      uniforms.uFogFar.value = linear.far
    }
    if (follow && meshRef.current) {
      meshRef.current.position.x = state.camera.position.x + (position?.[0] ?? 0)
      meshRef.current.position.z = state.camera.position.z + (position?.[2] ?? 0)
    }
  })

  const initX = follow ? 0 : (position?.[0] ?? 0)
  const initZ = follow ? 0 : (position?.[2] ?? 0)

  return (
    <mesh
      ref={meshRef}
      position={[initX, y, initZ]}
      rotation={[-Math.PI / 2 + rotation[0], rotation[1], rotation[2]]}
    >
      <planeGeometry args={[w, d, segments, segments]} />
      {nodeMaterial ? (
        <primitive object={nodeMaterial} attach="material" />
      ) : (
        <shaderMaterial
          uniforms={uniforms}
          vertexShader={VERTEX}
          fragmentShader={FRAGMENT}
          transparent
        />
      )}
    </mesh>
  )
}

// Mounted wherever the viewer is when a world streams.
Ocean.stream = false

import type { Color, Vector3 } from 'three'
import {
  cameraPosition,
  cos,
  distance,
  dot,
  float,
  max,
  mix,
  modelWorldMatrix,
  normalize,
  positionLocal,
  pow,
  reflect,
  sin,
  smoothstep,
  sRGBTransferEOTF,
  varying,
  vec2,
  vec3,
  vec4,
} from 'three/tsl'
import { MeshBasicNodeMaterial, type Node } from 'three/webgpu'
import { follow } from './uniforms'

/** What one body of water's waves and shading look like (the numbers its GLSL shader uses). */
export interface WaterShape {
  /** Wave frequencies: first wave x and y, second wave x and y, the diagonal chop. */
  freq: [number, number, number, number, number]
  /** How fast the diagonal chop runs against the clock. */
  chop: number
  /** Finite-difference step for the normal. */
  eps: number
  /** Waves in world XZ (they stay put while the mesh follows the camera) or in the mesh's own. */
  world: boolean
  /** How much sky tints the water at grazing angles. */
  sky: number
  /** Sun glint exponent and strength. */
  glint: [number, number]
  /** Crest brightening. */
  crest: number
  /** Base opacity, and what grazing angles add. */
  alpha: [number, number]
  /** Blend into distance fog (needs the fog uniforms). */
  fog: boolean
}

export interface WaterUniforms {
  uTime: { value: number }
  uWaveHeight: { value: number }
  uWaveSpeed: { value: number }
  uColorDeep: { value: Color }
  uColorShallow: { value: Color }
  uSunDir: { value: Vector3 }
  uFogColor?: { value: Color }
  uFogNear?: { value: number }
  uFogFar?: { value: number }
}

/** The node (TSL) twin of `Lake`'s and `Ocean`'s GLSL water, for `WebGPURenderer`. */
export function waterMaterial(record: WaterUniforms, shape: WaterShape) {
  const time = follow<Node<'float'>>(record.uTime)
  const waveHeight = follow<Node<'float'>>(record.uWaveHeight)
  const waveSpeed = follow<Node<'float'>>(record.uWaveSpeed)
  const deep = follow<Node<'vec3'>>(record.uColorDeep)
  const shallow = follow<Node<'vec3'>>(record.uColorShallow)
  const sunDir = follow<Node<'vec3'>>(record.uSunDir)
  const [fx1, fy1, fx2, fy2, fd] = shape.freq

  const waveH = (q: Node<'vec2'>, t: Node<'float'>): Node<'float'> => {
    const w1 = sin(q.x.mul(fx1).add(t)).mul(cos(q.y.mul(fy1).add(t.mul(0.8))))
    const w2 = sin(q.x.mul(fx2).sub(t.mul(0.7))).mul(sin(q.y.mul(fy2).add(t)))
    const w3 = sin(q.x.add(q.y).mul(fd).add(t.mul(shape.chop))).mul(0.25)
    return w1.add(w2).add(w3).mul(0.5) as Node<'float'>
  }

  const t = time.mul(waveSpeed)
  const q = (
    shape.world
      ? modelWorldMatrix.mul(vec4(positionLocal.x, positionLocal.y, 0, 1)).xz
      : positionLocal.xy
  ) as Node<'vec2'>
  const h = waveH(q, t)
  const hx = waveH(q.add(vec2(shape.eps, 0)), t)
  const hy = waveH(q.add(vec2(0, shape.eps)), t)
  const slope = waveHeight.div(shape.eps)
  const n = normalize(vec3(hx.sub(h).mul(slope).negate(), hy.sub(h).mul(slope).negate(), 1))
  const displaced = positionLocal.add(vec3(0, 0, h.mul(waveHeight)))

  const worldNormal = varying(normalize(modelWorldMatrix.mul(vec4(n, 0)).xyz))
  const worldPos = varying(modelWorldMatrix.mul(vec4(displaced, 1)).xyz)
  const wave = varying(h)

  const normal = normalize(worldNormal)
  const viewDir = normalize(cameraPosition.sub(worldPos))
  const m = smoothstep(-1, 1, wave)
  const fresnel = pow(float(1).sub(max(dot(normal, viewDir), 0)), 3)
  const glint = pow(max(dot(reflect(sunDir.negate(), normal), viewDir), 0), shape.glint[0])
  let color = mix(deep, shallow, m) as Node<'vec3'>
  color = mix(color, vec3(0.62, 0.78, 0.9), fresnel.mul(shape.sky)) as Node<'vec3'>
  color = color.add(vec3(1, 0.95, 0.85).mul(glint).mul(shape.glint[1])) as Node<'vec3'>
  color = color.add(pow(max(m.sub(0.6), 0), 2).mul(shape.crest)) as Node<'vec3'>
  let alpha = float(shape.alpha[0]).add(fresnel.mul(shape.alpha[1])) as Node<'float'>
  if (shape.fog && record.uFogColor && record.uFogNear && record.uFogFar) {
    const near = follow<Node<'float'>>(record.uFogNear)
    const far = follow<Node<'float'>>(record.uFogFar)
    const fog = smoothstep(near, far, distance(cameraPosition, worldPos))
    color = mix(color, follow<Node<'vec3'>>(record.uFogColor), fog) as Node<'vec3'>
    alpha = mix(alpha, float(1), fog) as Node<'float'>
  }

  const material = new MeshBasicNodeMaterial({ transparent: true })
  material.positionNode = displaced
  // The GLSL shader writes its color as is (no tone mapping, no output conversion); undoing the
  // node pipeline's sRGB output conversion here shows the same color.
  material.colorNode = vec4(sRGBTransferEOTF(color) as Node<'vec3'>, alpha)
  material.toneMapped = false
  material.fog = false
  return material
}

import { uniform } from 'three/tsl'
import type { Node } from 'three/webgpu'

/** A TSL uniform that follows `entry.value` every render, so the `{ value }` records a
 *  component already updates (for its GLSL material) drive its node material too. */
export function follow<N extends Node>(entry: { value: unknown }): N {
  return uniform(entry.value as never).onRenderUpdate(() => entry.value as never) as unknown as N
}
